// === Tab: mySketch ===
// A fork of Wobbly Swarm by Konstantin Makhmutov
// https://openprocessing.org/sketch/492096
//
const num=256 // number of pieces
const balls=[]
const massMin=.005
const massMax=.03

setup=()=>{
  createCanvas(windowWidth, windowHeight)
  for(let i=num;i--;){
    balls.push({
      mass:random(massMin,massMax),
      position:createVector(random(width),random(height)),
      velocity:createVector()
    })
  }
}

draw=()=>{
  background('black')

  const infulence=.92
  balls.push({
    mass:2,
    position:createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))),
    velocity:createVector()
  })

  for(const A of balls){
    const acceleration=createVector()
    for(const B of balls){
      if (A !== B) {
        const difference=p5.Vector.sub(B.position,A.position)
        const distance = max(1,sqrt(difference.x **2 + difference.y **2))
        const force = (distance - 320) * B.mass / distance
        acceleration.add(difference.mult(force))
      }
    }    
    A.velocity=A.velocity.mult(infulence).add(acceleration.mult(A.mass))
  }
  balls.pop()

  for (const A of balls) {
    A.position.add(A.velocity)
  }

  noStroke()
  for (const A of balls) {
    const r=map(A.mass,massMin,massMax,255,0)
    fill(r,r*3,255)
    ellipse(A.position.x, A.position.y, A.mass * 600);
  }
}

